    destinations.add(primary)
    mode = params['mode']
    receipt = params['receipt']
    if mode == 'mirror':
        destinations.add('slot:public')
    elif mode == 'linked':
        destinations.add(partner_slot)
    if receipt == 'external':
        destinations.add('slot:audit')
    elif receipt == 'partner' and params['route'] != 'partner':
        destinations.add(partner_slot)
    restricted = destinations.intersection(policy.keys())
    violating = {dest for dest in restricted if not label.subset.issubset(set(policy[dest]))}
    if violating:
        raise PolicyViolation(f'Unauthorized categories for destinations: {violating}')
